81	export default function AdminUsers() {
82	  const navigate = useNavigate();
83	  const [search, setSearch] = useState("");
84	  const [debouncedSearch, setDebouncedSearch] = useState("");
85	  const [planFilter, setPlanFilter] = useState<PlanType | "">("");
86	  const [roleFilter, setRoleFilter] = useState<UserRole | "">("");
87	  const [page, setPage] = useState(0);
88	  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
89	  const [sortAsc, setSortAsc] = useState(false);
90	
91	  // Simple debounce: update search on blur / Enter, or after typing stops
92	  const handleSearchChange = (e: React.ChangeEvent<HTMLInputElement>) => {
93	    setSearch(e.target.value);
94	  };
95	
96	  const handleSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
97	    if (e.key === "Enter") {
98	      setDebouncedSearch(search);
99	      setPage(0);
100	    }
101	  };
102	
103	  const handleSearchBlur = () => {
104	    setDebouncedSearch(search);
105	    setPage(0);
106	  };
107	
108	  const filter: AdminUsersFilter = {
109	    search: debouncedSearch || undefined,
110	    plan: planFilter || undefined,
111	    role: roleFilter || undefined,
112	  };
113	
114	  const { data, isLoading, isError } = useAdminUsers({
115	    page,
116	    pageSize: PAGE_SIZE,
117	    filter,
118	    sortColumn: sortColumn as keyof ProfileRow,
