121	
122	  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;
123	
124	  const handleSort = (col: SortableColumn) => {
125	    if (sortColumn === col) {
126	      setSortAsc((asc) => !asc);
127	    } else {
128	      setSortColumn(col);
129	      setSortAsc(true);
130	    }
131	    setPage(0);
132	  };
133	
134	  const SortableHeader = ({
135	    column,
136	    label,
137	  }: {
138	    column: SortableColumn;
139	    label: string;
140	  }) => (
141	    <TableHead
142	      className="cursor-pointer select-none whitespace-nowrap"
143	      onClick={() => handleSort(column)}
144	      aria-sort={
145	        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
146	      }
147	    >
148	      <span className="inline-flex items-center">
149	        {label}
150	        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
151	      </span>
152	    </TableHead>
153	  );
154	
155	  return (
156	    <div className="space-y-6">
157	      <PageHeader
158	        title="Users"
159	        description={
160	          data ? `${data.total.toLocaleString()} total users` : "All registered users"
161	        }
162	      />
