164	      {/* Filters */}
165	      <div className="flex flex-wrap items-center gap-3">
166	        <div className="relative flex-1 min-w-[200px] max-w-xs">
167	          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
168	          <Input
169	            placeholder="Search by email or name..."
170	            value={search}
171	            onChange={handleSearchChange}
172	            onKeyDown={handleSearchKeyDown}
173	            onBlur={handleSearchBlur}
174	            className="pl-9"
175	            aria-label="Search users"
176	          />
177	        </div>
178	
179	        <Select
180	          value={planFilter}
181	          onValueChange={(v) => {
182	            setPlanFilter(v as PlanType | "");
183	            setPage(0);
184	          }}
185	        >
186	          <SelectTrigger className="w-[130px]" aria-label="Filter by plan">
187	            <SelectValue placeholder="All plans" />
188	          </SelectTrigger>
189	          <SelectContent>
190	            <SelectItem value="">All plans</SelectItem>
191	            <SelectItem value="free">Free</SelectItem>
192	            <SelectItem value="pro">Pro</SelectItem>
193	            <SelectItem value="agency">Agency</SelectItem>
194	          </SelectContent>
195	        </Select>
196	
197	        <Select
198	          value={roleFilter}
199	          onValueChange={(v) => {
200	            setRoleFilter(v as UserRole | "");
201	            setPage(0);
202	          }}
203	        >
204	          <SelectTrigger className="w-[150px]" aria-label="Filter by role">
205	            <SelectValue placeholder="All roles" />
206	          </SelectTrigger>
207	          <SelectContent>
208	            <SelectItem value="">All roles</SelectItem>
209	            <SelectItem value="user">User</SelectItem>
210	            <SelectItem value="admin">Admin</SelectItem>
211	            <SelectItem value="super_admin">Super Admin</SelectItem>
212	          </SelectContent>
213	        </Select>
214	
215	        {(debouncedSearch || planFilter || roleFilter) && (
216	          <Button
217	            variant="ghost"
218	            size="sm"
219	            onClick={() => {
220	              setSearch("");
221	              setDebouncedSearch("");
222	              setPlanFilter("");
223	              setRoleFilter("");
224	              setPage(0);
225	            }}
226	          >
227	            Clear filters
228	          </Button>
229	        )}
230	      </div>
231	
232	      {/* Table */}
233	      <div className="rounded-xl border border-slate-200 overflow-hidden">
234	        <Table>
235	          <TableHeader>
236	            <TableRow className="bg-slate-50 hover:bg-slate-50">
