238	              <SortableHeader column="full_name" label="Name" />
239	              <SortableHeader column="plan" label="Plan" />
240	              <SortableHeader column="scans_used" label="Scans Used" />
241	              <SortableHeader column="role" label="Role" />
242	              <SortableHeader column="created_at" label="Signed Up" />
243	              <TableHead className="w-10" />
244	            </TableRow>
245	          </TableHeader>
246	          <TableBody>
247	            {isLoading ? (
248	              <TableSkeleton />
