274	                  aria-label={`View user ${user.email}`}
275	                >
276	                  <TableCell className="font-mono text-xs text-muted-foreground">
277	                    {user.email}
278	                  </TableCell>
279	                  <TableCell className="text-sm font-medium">
280	                    <div className="flex items-center gap-1.5">
281	                      {user.full_name || (
282	                        <span className="text-muted-foreground/50">—</span>
283	                      )}
284	                      {user.is_banned && (
285	                        <Badge className="bg-red-100 text-red-700 border-0 text-[10px] px-1.5 py-0">
286	                          Banned
287	                        </Badge>
288	                      )}
289	                    </div>
290	                  </TableCell>
291	                  <TableCell>
292	                    <Badge
293	                      className={`text-[11px] px-2 py-0.5 capitalize ${
294	                        PLAN_BADGE_CLASSES[user.plan]
295	                      }`}
296	                    >
297	                      {user.plan}
298	                    </Badge>
299	                  </TableCell>
300	                  <TableCell className="text-sm text-muted-foreground">
301	                    {user.scans_used} / {user.scan_limit}
302	                  </TableCell>
303	                  <TableCell>
304	                    <Badge
305	                      className={`text-[11px] px-2 py-0.5 capitalize ${
306	                        ROLE_BADGE_CLASSES[user.role]
307	                      }`}
308	                    >
309	                      {user.role.replace("_", " ")}
310	                    </Badge>
311	                  </TableCell>
312	                  <TableCell className="text-sm text-muted-foreground">
313	                    {format(new Date(user.created_at), "MMM d, yyyy")}
314	                  </TableCell>
315	                  <TableCell>
316	                    <ChevronRight className="h-4 w-4 text-slate-300" />
317	                  </TableCell>
318	                </TableRow>
319	              ))
320	            )}
321	          </TableBody>
322	        </Table>
323	      </div>
324	
325	      {/* Pagination */}
326	      {totalPages > 1 && (
327	        <div className="flex items-center justify-between">
328	          <p className="text-sm text-muted-foreground">
329	            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()} users)
330	          </p>
331	          <div className="flex items-center gap-2">
332	            <Button
333	              variant="outline"
334	              size="sm"
335	              onClick={() => setPage((p) => Math.max(0, p - 1))}
336	              disabled={page === 0}
337	              aria-label="Previous page"
338	            >
339	              <ChevronLeft className="h-4 w-4" />
340	            </Button>
341	            <Button
342	              variant="outline"
343	              size="sm"
344	              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
345	              disabled={page >= totalPages - 1}
346	              aria-label="Next page"
347	            >
348	              <ChevronRight className="h-4 w-4" />
349	            </Button>
350	          </div>
351	        </div>
352	      )}
353	    </div>
354	  );
355	}
