1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import type { ProfileRow } from "@/types/database";
4	import type { PlanType, UserRole } from "@/types/index";
5	
6	export interface AdminUsersFilter {
7	  search?: string;
8	  plan?: PlanType | "";
9	  role?: UserRole | "";
10	}
11	
12	export interface AdminUsersResult {
13	  users: ProfileRow[];
14	  total: number;
15	}
16	
17	interface FetchAdminUsersParams {
18	  page: number;
19	  pageSize: number;
20	  filter: AdminUsersFilter;
21	  sortColumn: keyof ProfileRow;
22	  sortAsc: boolean;
23	}
24	
25	const PAGE_SIZE = 20;
26	
27	async function fetchAdminUsers({
28	  page,
29	  pageSize,
30	  filter,
31	  sortColumn,
32	  sortAsc,
33	}: FetchAdminUsersParams): Promise<AdminUsersResult> {
34	  let query = supabase
35	    .from("profiles")
36	    .select("*", { count: "exact" });
37	
38	  if (filter.search) {
39	    // Use ilike for case-insensitive search across email and full_name
40	    query = query.or(
41	      `email.ilike.%${filter.search}%,full_name.ilike.%${filter.search}%`
42	    );
43	  }
44	
45	  if (filter.plan) {
46	    query = query.eq("plan", filter.plan);
47	  }
48	
49	  if (filter.role) {
50	    query = query.eq("role", filter.role);
51	  }
52	
53	  const from = page * pageSize;
54	  const to = from + pageSize - 1;
55	
56	  query = query
57	    .order(sortColumn as string, { ascending: sortAsc })
58	    .range(from, to);
59	
60	  const { data, count, error } = await query;
61	
62	  if (error) throw new Error(error.message);
63	
64	  return {
65	    users: (data ?? []) as ProfileRow[],
66	    total: count ?? 0,
67	  };
68	}
69	
70	export function useAdminUsers(params: {
71	  page?: number;
72	  pageSize?: number;
73	  filter?: AdminUsersFilter;
74	  sortColumn?: keyof ProfileRow;
75	  sortAsc?: boolean;
76	}) {
77	  const {
78	    page = 0,
79	    pageSize = PAGE_SIZE,
80	    filter = {},
81	    sortColumn = "created_at",
82	    sortAsc = false,
83	  } = params;
84	
85	  return useQuery({
86	    queryKey: ["admin", "users", { page, pageSize, filter, sortColumn, sortAsc }],
87	    queryFn: () =>
88	      fetchAdminUsers({ page, pageSize, filter, sortColumn, sortAsc }),
89	    staleTime: 30_000,
90	    placeholderData: (prev) => prev,
91	  });
92	}
