import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { ScanRow } from "@/types/database";
import type { ScanStatus } from "@/types/index";
import { toast } from "sonner";

// ── Extended scan row with joined user profile ────────────────

export interface AdminScanRow extends ScanRow {
  user_email?: string;
  user_name?: string;
}

// ── Filters ───────────────────────────────────────────────────

export interface AdminScansFilter {
  search?: string;
  status?: ScanStatus | "";
  scoreLte?: number;
  scoreGte?: number;
  dateFrom?: string;
  dateTo?: string;
}

export interface AdminScansResult {
  scans: AdminScanRow[];
  total: number;
}

// ── Aggregate stats ───────────────────────────────────────────

export interface AdminScanStats {
  totalScans: number;
  avgScore: number;
  failedScans: number;
  scansToday: number;
}

// ── Fetch helpers ─────────────────────────────────────────────

interface FetchAdminScansParams {
  page: number;
  pageSize: number;
  filter: AdminScansFilter;
  sortColumn: keyof ScanRow;
  sortAsc: boolean;
}

async function fetchAdminScans({
  page,
  pageSize,
  filter,
  sortColumn,
  sortAsc,
}: FetchAdminScansParams): Promise<AdminScansResult> {
  // Fetch scans with joined profile for user email/name
  let query = supabase
    .from("scans")
    .select(
      `
      *,
      profiles:user_id (
        email,
        full_name
      )
    `,
      { count: "exact" }
    )
    .order(sortColumn as string, { ascending: sortAsc });

  if (filter.status) {
    query = query.eq("status", filter.status);
  }

  if (filter.scoreGte !== undefined && filter.scoreGte > 0) {
    query = query.gte("overall_score", filter.scoreGte);
  }

  if (filter.scoreLte !== undefined && filter.scoreLte < 100) {
    query = query.lte("overall_score", filter.scoreLte);
  }

  if (filter.dateFrom) {
    query = query.gte("created_at", filter.dateFrom);
  }

  if (filter.dateTo) {
    query = query.lte("created_at", filter.dateTo);
  }

  const from = page * pageSize;
  const to = from + pageSize - 1;
  query = query.range(from, to);

  const { data, count, error } = await query;

  if (error) throw new Error(error.message);

  const scans: AdminScanRow[] = (data ?? []).map((row) => {
    const profileData = row.profiles as
      | { email: string; full_name: string | null }
      | null;

    // Filter search client-side after fetch if needed
    return {
      id: row.id,
      user_id: row.user_id,
      url: row.url,
      favicon_url: row.favicon_url,
      page_title: row.page_title,
      page_type: row.page_type,
      status: row.status,
      overall_score: row.overall_score,
      issues_found: row.issues_found,
      critical_issues: row.critical_issues,
      warnings: row.warnings,
      quick_wins: row.quick_wins,
      screenshot_url: row.screenshot_url,
      device: row.device,
      error_message: row.error_message,
      created_at: row.created_at,
      completed_at: row.completed_at,
      user_email: profileData?.email,
      user_name: profileData?.full_name ?? undefined,
    };
  });

  // Apply search filter after joining (Supabase can't ilike on joined columns directly)
  const filtered = filter.search
    ? scans.filter(
        (s) =>
          s.url.toLowerCase().includes(filter.search!.toLowerCase()) ||
          (s.user_email ?? "")
            .toLowerCase()
            .includes(filter.search!.toLowerCase())
      )
    : scans;

  return {
    scans: filtered,
    total: filter.search ? filtered.length : (count ?? 0),
  };
}

async function fetchAdminScanStats(): Promise<AdminScanStats> {
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const [
    { count: totalScans, error: totalError },
    { count: failedScans, error: failedError },
    { count: scansToday, error: todayError },
    { data: scoreData, error: scoreError },
  ] = await Promise.all([
    supabase.from("scans").select("*", { count: "exact", head: true }),
    supabase
      .from("scans")
      .select("*", { count: "exact", head: true })
      .eq("status", "failed"),
    supabase
      .from("scans")
      .select("*", { count: "exact", head: true })
      .gte("created_at", todayStart.toISOString()),
    supabase
      .from("scans")
      .select("overall_score")
      .eq("status", "completed")
      .not("overall_score", "is", null),
  ]);

  if (totalError) throw new Error(totalError.message);
  if (failedError) throw new Error(failedError.message);
  if (todayError) throw new Error(todayError.message);
  if (scoreError) throw new Error(scoreError.message);

  const scores = (scoreData ?? [])
    .map((r) => r.overall_score as number)
    .filter((s) => s !== null);

  const avgScore =
    scores.length > 0
      ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length)
      : 0;

  return {
    totalScans: totalScans ?? 0,
    avgScore,
    failedScans: failedScans ?? 0,
    scansToday: scansToday ?? 0,
  };
}

// ── Hooks ─────────────────────────────────────────────────────

export function useAdminScans(params: {
  page?: number;
  pageSize?: number;
  filter?: AdminScansFilter;
  sortColumn?: keyof ScanRow;
  sortAsc?: boolean;
}) {
  const {
    page = 0,
    pageSize = 25,
    filter = {},
    sortColumn = "created_at",
    sortAsc = false,
  } = params;

  return useQuery({
    queryKey: ["admin", "scans", { page, pageSize, filter, sortColumn, sortAsc }],
    queryFn: () =>
      fetchAdminScans({ page, pageSize, filter, sortColumn, sortAsc }),
    staleTime: 30_000,
    placeholderData: (prev) => prev,
  });
}

export function useAdminScanStats() {
  return useQuery({
    queryKey: ["admin", "scan-stats"],
    queryFn: fetchAdminScanStats,
    staleTime: 60_000,
  });
}

export function useDeleteScan() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string) => {
      // Delete scan_results first (FK constraint)
      const { error: resultsError } = await supabase
        .from("scan_results")
        .delete()
        .eq("scan_id", scanId);

      if (resultsError) throw new Error(resultsError.message);

      const { error } = await supabase
        .from("scans")
        .delete()
        .eq("id", scanId);

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Scan deleted");
      queryClient.invalidateQueries({ queryKey: ["admin", "scans"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "scan-stats"] });
      queryClient.invalidateQueries({ queryKey: ["admin", "stats"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to delete scan: ${error.message}`);
    },
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { AuditLogEntry } from "./use-audit-log";

// ── Plan prices ───────────────────────────────────────────────
// Keep in sync with use-admin-actions.ts plan limits

export const PLAN_PRICES: Record<string, number> = {
  free: 0,
  pro: 49,
  agency: 199,
};

// ── Types ─────────────────────────────────────────────────────

export interface PlanDistribution {
  free: number;
  pro: number;
  agency: number;
}

export interface BillingStats {
  mrr: number;
  annualProjection: number;
  activeSubscriptions: number;
  freeUsers: number;
  planDistribution: PlanDistribution;
}

export interface PlanChangeEntry extends AuditLogEntry {
  previous_plan?: string;
  new_plan?: string;
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchBillingStats(): Promise<BillingStats> {
  const { data, error } = await supabase
    .from("profiles")
    .select("plan");

  if (error) throw new Error(error.message);

  const profiles = data ?? [];

  const planDistribution: PlanDistribution = { free: 0, pro: 0, agency: 0 };

  for (const p of profiles) {
    const plan = p.plan as keyof PlanDistribution;
    if (plan in planDistribution) {
      planDistribution[plan]++;
    }
  }

  const mrr =
    planDistribution.pro * PLAN_PRICES.pro +
    planDistribution.agency * PLAN_PRICES.agency;

  const annualProjection = mrr * 12;

  const activeSubscriptions = planDistribution.pro + planDistribution.agency;

  return {
    mrr,
    annualProjection,
    activeSubscriptions,
    freeUsers: planDistribution.free,
    planDistribution,
  };
}

async function fetchRecentPlanChanges(): Promise<PlanChangeEntry[]> {
  const { data, error } = await supabase
    .from("audit_logs")
    .select(
      `
      *,
      profiles:admin_id (
        email,
        full_name
      )
    `
    )
    .eq("action", "change_plan")
    .order("created_at", { ascending: false })
    .limit(20);

  if (error) throw new Error(error.message);

  return (data ?? []).map((row) => {
    const profileData = row.profiles as
      | { email: string; full_name: string | null }
      | null;
    const metadata = row.metadata as Record<string, string>;

    return {
      id: row.id,
      admin_id: row.admin_id,
      action: row.action,
      target_type: row.target_type,
      target_id: row.target_id,
      metadata: row.metadata as Record<string, unknown>,
      created_at: row.created_at,
      admin_email: profileData?.email,
      admin_name: profileData?.full_name ?? undefined,
      previous_plan: metadata?.previous_plan,
      new_plan: metadata?.new_plan,
    };
  });
}

// ── Hooks ─────────────────────────────────────────────────────

export function useAdminBilling() {
  return useQuery({
    queryKey: ["admin", "billing"],
    queryFn: fetchBillingStats,
    staleTime: 60_000,
  });
}

export function useRecentPlanChanges() {
  return useQuery({
    queryKey: ["admin", "plan-changes"],
    queryFn: fetchRecentPlanChanges,
    staleTime: 30_000,
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { toast } from "sonner";

// ── Types ─────────────────────────────────────────────────────

export interface SystemStats {
  profilesCount: number;
  scansCount: number;
  scanResultsCount: number;
  screenshotsCount: number;
  supabaseConnected: boolean;
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchSystemStats(): Promise<SystemStats> {
  const [
    { count: profilesCount, error: profilesError },
    { count: scansCount, error: scansError },
    { count: scanResultsCount, error: resultsError },
    { count: screenshotsCount, error: screenshotsError },
  ] = await Promise.all([
    supabase.from("profiles").select("*", { count: "exact", head: true }),
    supabase.from("scans").select("*", { count: "exact", head: true }),
    supabase.from("scan_results").select("*", { count: "exact", head: true }),
    supabase
      .from("scans")
      .select("*", { count: "exact", head: true })
      .not("screenshot_url", "is", null),
  ]);

  // If any query succeeded, Supabase is connected. Errors indicate permission issues, not connectivity.
  const supabaseConnected = !profilesError || profilesError.code !== "PGRST301";

  return {
    profilesCount: profilesCount ?? 0,
    scansCount: scansCount ?? 0,
    scanResultsCount: scanResultsCount ?? 0,
    screenshotsCount: screenshotsCount ?? 0,
    supabaseConnected,
  };
}

// ── Hooks ─────────────────────────────────────────────────────

export function useSystemStats() {
  return useQuery({
    queryKey: ["admin", "system-stats"],
    queryFn: fetchSystemStats,
    staleTime: 30_000,
  });
}

export function useResetMonthlyScans() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const { error } = await supabase.rpc("reset_monthly_scans");
      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Monthly scan counters reset for all users");
      queryClient.invalidateQueries({ queryKey: ["admin"] });
    },
    onError: (error: Error) => {
      toast.error(`Reset failed: ${error.message}`);
    },
  });
}

export function useClearFailedScans() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const thirtyDaysAgo = new Date(
        Date.now() - 30 * 24 * 60 * 60 * 1000
      ).toISOString();

      // Delete scan_results for old failed scans first
      const { data: failedScans, error: fetchError } = await supabase
        .from("scans")
        .select("id")
        .eq("status", "failed")
        .lte("created_at", thirtyDaysAgo);

      if (fetchError) throw new Error(fetchError.message);

      const scanIds = (failedScans ?? []).map((s) => s.id);

      if (scanIds.length === 0) {
        return 0;
      }

      const { error: resultsError } = await supabase
        .from("scan_results")
        .delete()
        .in("scan_id", scanIds);

      if (resultsError) throw new Error(resultsError.message);

      const { count, error: deleteError } = await supabase
        .from("scans")
        .delete({ count: "exact" })
        .eq("status", "failed")
        .lte("created_at", thirtyDaysAgo);

      if (deleteError) throw new Error(deleteError.message);

      return count ?? 0;
    },
    onSuccess: (count) => {
      toast.success(
        count === 0
          ? "No old failed scans to clear"
          : `Cleared ${count} failed scan${count === 1 ? "" : "s"}`
      );
      queryClient.invalidateQueries({ queryKey: ["admin"] });
    },
    onError: (error: Error) => {
      toast.error(`Clear failed: ${error.message}`);
    },
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { ProfileRow } from "@/types/database";

// ── Types ─────────────────────────────────────────────────────

export interface AtRiskUser extends ProfileRow {
  has_failed_scans: boolean;
  never_scanned: boolean;
  at_scan_limit: boolean;
  last_scan_date: string | null;
}

export interface SupportStats {
  usersAtLimit: number;
  usersWithFailedScans: number;
  newSignupsLastWeek: number;
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchAtRiskUsers(): Promise<AtRiskUser[]> {
  const sevenDaysAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000
  ).toISOString();

  // Fetch all profiles
  const { data: profiles, error: profilesError } = await supabase
    .from("profiles")
    .select("*")
    .order("created_at", { ascending: false })
    .limit(200);

  if (profilesError) throw new Error(profilesError.message);

  // Fetch users with failed scans in last 7 days
  const { data: failedScansData, error: failedError } = await supabase
    .from("scans")
    .select("user_id")
    .eq("status", "failed")
    .gte("created_at", sevenDaysAgo);

  if (failedError) throw new Error(failedError.message);

  // Fetch most recent scan per user
  const { data: lastScans, error: lastScansError } = await supabase
    .from("scans")
    .select("user_id, created_at")
    .order("created_at", { ascending: false });

  if (lastScansError) throw new Error(lastScansError.message);

  const failedUserIds = new Set(
    (failedScansData ?? []).map((r) => r.user_id)
  );

  // Build a map of user_id → last scan date
  const lastScanMap = new Map<string, string>();
  for (const scan of lastScans ?? []) {
    if (!lastScanMap.has(scan.user_id)) {
      lastScanMap.set(scan.user_id, scan.created_at);
    }
  }

  const atRisk: AtRiskUser[] = [];

  for (const profile of profiles ?? []) {
    const p = profile as ProfileRow;
    const atLimit = p.scans_used >= p.scan_limit;
    const hasFailed = failedUserIds.has(p.id);
    const neverScanned = !lastScanMap.has(p.id);
    const lastScanDate = lastScanMap.get(p.id) ?? null;

    if (atLimit || hasFailed || neverScanned) {
      atRisk.push({
        ...p,
        has_failed_scans: hasFailed,
        never_scanned: neverScanned,
        at_scan_limit: atLimit,
        last_scan_date: lastScanDate,
      });
    }
  }

  // Sort: at limit first, then failed scans, then never scanned
  return atRisk.sort((a, b) => {
    const scoreA = (a.at_scan_limit ? 3 : 0) + (a.has_failed_scans ? 2 : 0) + (a.never_scanned ? 1 : 0);
    const scoreB = (b.at_scan_limit ? 3 : 0) + (b.has_failed_scans ? 2 : 0) + (b.never_scanned ? 1 : 0);
    return scoreB - scoreA;
  });
}

async function fetchSupportStats(): Promise<SupportStats> {
  const sevenDaysAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000
  ).toISOString();

  const [
    { data: profiles, error: profilesError },
    { data: failedScans, error: failedError },
    { count: newSignups, error: signupsError },
  ] = await Promise.all([
    supabase.from("profiles").select("scans_used, scan_limit"),
    supabase
      .from("scans")
      .select("user_id")
      .eq("status", "failed")
      .gte("created_at", sevenDaysAgo),
    supabase
      .from("profiles")
      .select("*", { count: "exact", head: true })
      .gte("created_at", sevenDaysAgo),
  ]);

  if (profilesError) throw new Error(profilesError.message);
  if (failedError) throw new Error(failedError.message);
  if (signupsError) throw new Error(signupsError.message);

  const usersAtLimit = (profiles ?? []).filter(
    (p) => p.scans_used >= p.scan_limit
  ).length;

  const usersWithFailedScans = new Set(
    (failedScans ?? []).map((r) => r.user_id)
  ).size;

  return {
    usersAtLimit,
    usersWithFailedScans,
    newSignupsLastWeek: newSignups ?? 0,
  };
}

// ── Hooks ─────────────────────────────────────────────────────

export function useAtRiskUsers() {
  return useQuery({
    queryKey: ["admin", "at-risk-users"],
    queryFn: fetchAtRiskUsers,
    staleTime: 60_000,
  });
}

export function useSupportStats() {
  return useQuery({
    queryKey: ["admin", "support-stats"],
    queryFn: fetchSupportStats,
    staleTime: 60_000,
  });
}

