function SortIcon({
  column,
  sortColumn,
  sortAsc,
}: {
  column: SortableColumn;
  sortColumn: SortableColumn;
  sortAsc: boolean;
}) {
  if (sortColumn !== column)
    return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-slate-300" />;
  return sortAsc ? (
    <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
  ) : (
    <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />
  );
}

function ScoreDisplay({ score }: { score: number | null }) {
  if (score === null) return <span className="text-muted-foreground/50">—</span>;
  const color =
    score >= 75
      ? "text-green-600"
      : score >= 50
      ? "text-amber-600"
      : "text-red-600";
  return (
    <span className={`font-semibold tabular-nums ${color}`}>{score}</span>
  );
}

