          <KpiCard
            title="Avg Score"
            value={statsQuery.data?.avgScore ?? 0}
            icon={CheckCircle2}
            iconColor="text-green-600"
            iconBg="bg-green-100"
            suffix="/100"
          />
          <KpiCard
            title="Failed Scans"
            value={statsQuery.data?.failedScans ?? 0}
            icon={AlertTriangle}
            iconColor="text-red-600"
            iconBg="bg-red-100"
          />
          <KpiCard
            title="Scans Today"
            value={statsQuery.data?.scansToday ?? 0}
            icon={Clock}
            iconColor="text-sky-600"
            iconBg="bg-sky-100"
          />
        </div>
      )}

