function PlanBarChart({
  free,
  pro,
  agency,
}: {
  free: number;
  pro: number;
  agency: number;
}) {
  const total = free + pro + agency || 1; // avoid divide by zero

  const bars = [
    {
      label: "Free",
      count: free,
      pct: Math.round((free / total) * 100),
      barColor: "bg-slate-300",
      badgeClass: PLAN_BADGE_CLASSES.free,
    },
    {
      label: "Pro",
      count: pro,
      pct: Math.round((pro / total) * 100),
      barColor: "bg-indigo-500",
      badgeClass: PLAN_BADGE_CLASSES.pro,
    },
    {
      label: "Agency",
      count: agency,
      pct: Math.round((agency / total) * 100),
      barColor: "bg-purple-500",
      badgeClass: PLAN_BADGE_CLASSES.agency,
    },
  ];

  return (
    <div className="space-y-4">
