            <span className="text-xs font-medium text-muted-foreground">
              {bar.pct}%
            </span>
          </div>
          <div className="h-2 w-full rounded-full bg-slate-100 overflow-hidden">
            <div
              className={`h-full rounded-full transition-all duration-500 ${bar.barColor}`}
              style={{ width: `${bar.pct}%` }}
