                      grows.
                    </p>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

/**
 * Feature Flags page.
 *
 * Flags are stored in localStorage for now.
 * TODO: Move to a `system_config` Supabase table.
 *       Migration: CREATE TABLE system_config (key TEXT PRIMARY KEY, value JSONB, updated_at TIMESTAMPTZ DEFAULT NOW());
 *       RLS: Only super_admin can read/write.
 */

import { useState, useCallback } from "react";
import { Flag, AlertTriangle, Clock } from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { format } from "date-fns";

// ── Flag definitions ──────────────────────────────────────────

interface FeatureFlag {
  key: string;
  label: string;
  description: string;
  defaultValue: boolean;
  category: "ui" | "feature" | "system";
  requiresSuperAdmin?: boolean;
}

const FLAG_DEFINITIONS: FeatureFlag[] = [
  {
    key: "agent_hub_enabled",
    label: "AI Agent Hub",
    description: "Show the AI Agent Hub section in the user sidebar navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "integrations_enabled",
    label: "Integrations Page",
    description:
      "Show the Integrations page (Hotjar, GA4, Clarity, Search Console) in user navigation.",
    defaultValue: true,
    category: "ui",
  },
  {
    key: "pdf_export_enabled",
    label: "PDF Export",
    description:
      "Allow users to download audit reports as PDF. Requires a PDF generation service.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "email_notifications_enabled",
    label: "Email Notifications",
    description:
      "Send email alerts when scan completes, plan changes, or usage limit is reached.",
    defaultValue: false,
    category: "feature",
  },
  {
    key: "free_scan_enabled",
    label: "Public Scan (No Auth)",
    description:
      "Allow anonymous users to run a scan without signing in. Uses rate limiting.",
    defaultValue: true,
    category: "feature",
  },
  {
    key: "maintenance_mode",
    label: "Maintenance Mode",
    description:
      "Show a maintenance banner to all users. Does not block access — visual notice only.",
    defaultValue: false,
    category: "system",
    requiresSuperAdmin: true,
  },
];

const CATEGORY_LABELS: Record<FeatureFlag["category"], string> = {
  ui: "UI",
  feature: "Feature",
  system: "System",
};

const CATEGORY_BADGE_CLASSES: Record<FeatureFlag["category"], string> = {
  ui: "bg-sky-100 text-sky-700 border-0",
  feature: "bg-indigo-100 text-indigo-700 border-0",
  system: "bg-red-100 text-red-700 border-0",
};

// ── localStorage helpers ──────────────────────────────────────

const LS_KEY = "crobot_feature_flags";

interface StoredFlags {
  values: Record<string, boolean>;
  timestamps: Record<string, number>;
}

function loadFlags(): StoredFlags {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (!raw) return { values: {}, timestamps: {} };
    return JSON.parse(raw) as StoredFlags;
  } catch {
    return { values: {}, timestamps: {} };
  }
}

function saveFlags(stored: StoredFlags): void {
  localStorage.setItem(LS_KEY, JSON.stringify(stored));
}

function getFlagValue(stored: StoredFlags, key: string, defaultValue: boolean): boolean {
  return key in stored.values ? stored.values[key] : defaultValue;
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminFeatureFlags() {
  const [stored, setStored] = useState<StoredFlags>(() => loadFlags());

  const handleToggle = useCallback(
    (flag: FeatureFlag, enabled: boolean) => {
      const next: StoredFlags = {
        values: { ...stored.values, [flag.key]: enabled },
        timestamps: { ...stored.timestamps, [flag.key]: Date.now() },
      };
      setStored(next);
      saveFlags(next);
      toast.success(
        `${flag.label} ${enabled ? "enabled" : "disabled"}`
      );
    },
    [stored]
  );

  const categories: FeatureFlag["category"][] = ["ui", "feature", "system"];

  return (
    <div className="space-y-8">
      <PageHeader
        title="Feature Flags"
        description="Toggle features on/off across the platform."
      />

      {/* Local storage warning banner */}
      <div
        role="alert"
        className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3.5"
      >
        <AlertTriangle className="h-4 w-4 text-amber-500 mt-0.5 shrink-0" />
        <div className="flex-1">
          <p className="text-sm font-medium text-amber-800">
            Flags stored locally
          </p>
          <p className="text-xs text-amber-700 mt-0.5">
            Feature flags are stored in this browser's localStorage only.
            {/* TODO: Move to database — migrate system_config table */}
            Deploy the{" "}
            <code className="font-mono text-[11px] bg-amber-100 px-1 py-0.5 rounded">
              system_config
            </code>{" "}
            database migration for production-wide flag management.
          </p>
        </div>
      </div>

      {/* Flags by category */}
      {categories.map((category) => {
        const flags = FLAG_DEFINITIONS.filter((f) => f.category === category);

        return (
          <Card key={category} className="border-slate-200 shadow-none">
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Flag className="h-4 w-4 text-muted-foreground" />
                <CardTitle className="text-base font-semibold capitalize">
                  {category === "ui"
                    ? "UI Visibility"
                    : category === "feature"
                    ? "Feature Toggles"
                    : "System Flags"}
                </CardTitle>
              </div>
            </CardHeader>
            <CardContent className="divide-y divide-slate-100">
              {flags.map((flag) => {
                const enabled = getFlagValue(stored, flag.key, flag.defaultValue);
                const changedAt = stored.timestamps[flag.key];

                return (
                  <div
                    key={flag.key}
                    className="flex items-start gap-4 py-4 first:pt-0 last:pb-0"
                  >
                    {/* Toggle */}
                    <div className="pt-0.5">
                      <Switch
                        id={flag.key}
                        checked={enabled}
                        onCheckedChange={(v) => handleToggle(flag, v)}
                        aria-label={`Toggle ${flag.label}`}
                      />
                    </div>

                    {/* Info */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Label
                          htmlFor={flag.key}
                          className="text-sm font-medium cursor-pointer"
                        >
                          {flag.label}
                        </Label>
                        <Badge
                          className={`text-[10px] px-1.5 py-0 ${
                            CATEGORY_BADGE_CLASSES[flag.category]
                          }`}
                        >
                          {CATEGORY_LABELS[flag.category]}
                        </Badge>
                        {flag.requiresSuperAdmin && (
                          <Badge className="bg-red-50 text-red-600 border-red-200 text-[10px] px-1.5 py-0">
                            Super Admin
                          </Badge>
                        )}
                      </div>
                      <p className="mt-1 text-xs text-muted-foreground leading-relaxed">
                        {flag.description}
                      </p>
                      {changedAt && (
                        <div className="mt-1.5 flex items-center gap-1 text-[10px] text-muted-foreground/60">
                          <Clock className="h-2.5 w-2.5" />
                          <span>
                            Last changed{" "}
                            {format(new Date(changedAt), "MMM d, yyyy 'at' h:mm a")}
                          </span>
                        </div>
                      )}
                    </div>

                    {/* Status pill */}
                    <div className="shrink-0 pt-0.5">
                      <Badge
                        className={
                          enabled
                            ? "bg-green-100 text-green-700 border-0 text-[11px]"
                            : "bg-slate-100 text-slate-500 border-0 text-[11px]"
                        }
                      >
                        {enabled ? "On" : "Off"}
                      </Badge>
                    </div>
                  </div>
                );
              })}
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}

import {
  LifeBuoy,
  AlertTriangle,
  Users,
  UserCheck,
  ScanLine,
  Calendar,
  CheckCircle2,
  XCircle,
  MinusCircle,
  ChevronRight,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import { PageHeader } from "@/components/shared/PageHeader";
import { KpiCard } from "@/components/shared/KpiCard";
import { EmptyState } from "@/components/shared/EmptyState";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { useAtRiskUsers, useSupportStats } from "@/hooks/admin/use-admin-support";
import type { PlanType } from "@/types/index";
import { format, formatDistanceToNow } from "date-fns";

// ── Constants ─────────────────────────────────────────────────

const PLAN_BADGE_CLASSES: Record<PlanType, string> = {
  free: "bg-slate-100 text-slate-600 border-0",
  pro: "bg-indigo-100 text-indigo-700 border-0",
  agency: "bg-purple-100 text-purple-700 border-0",
};

// ── Sub-components ────────────────────────────────────────────

function KpiSkeleton() {
  return (
    <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
      {Array.from({ length: 3 }).map((_, i) => (
        <Skeleton key={i} className="h-[120px] rounded-xl" />
      ))}
    </div>
  );
}

function TableSkeleton() {
  return (
    <>
      {Array.from({ length: 6 }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: 7 }).map((__, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full max-w-[100px]" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

function RiskBadge({ active, label }: { active: boolean; label: string }) {
  if (!active) return null;
  return (
    <Badge className="bg-red-100 text-red-700 border-0 text-[10px] px-1.5 py-0">
      {label}
    </Badge>
  );
}

function StatusIcon({ active }: { active: boolean }) {
  return active ? (
    <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />
  ) : (
    <XCircle className="h-3.5 w-3.5 text-red-500" />
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminSupport() {
  const navigate = useNavigate();
  const atRiskQuery = useAtRiskUsers();
  const statsQuery = useSupportStats();

  return (
    <div className="space-y-8">
      <PageHeader
        title="Support"
        description="Identify users who may need help — at scan limits, failed scans, or inactive."
      />

      {/* Quick stats KPI row */}
      {statsQuery.isLoading ? (
        <KpiSkeleton />
      ) : statsQuery.isError ? (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
        >
          Failed to load support stats.
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
          <KpiCard
            title="At Scan Limit"
            value={statsQuery.data?.usersAtLimit ?? 0}
            icon={AlertTriangle}
            iconColor="text-amber-600"
            iconBg="bg-amber-100"
          />
          <KpiCard
            title="Failed Scans (7d)"
            value={statsQuery.data?.usersWithFailedScans ?? 0}
            icon={XCircle}
            iconColor="text-red-600"
            iconBg="bg-red-100"
          />
          <KpiCard
            title="New Signups (7d)"
            value={statsQuery.data?.newSignupsLastWeek ?? 0}
            icon={UserCheck}
            iconColor="text-green-600"
            iconBg="bg-green-100"
          />
        </div>
      )}

      {/* Contact requests — no table yet */}
      <Card className="border-slate-200 shadow-none">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <LifeBuoy className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base font-semibold">
              Contact Requests
            </CardTitle>
          </div>
        </CardHeader>
        <CardContent>
          <div className="rounded-xl border border-dashed border-slate-200 px-6 py-10 text-center">
            <LifeBuoy className="mx-auto h-10 w-10 text-slate-300 mb-3" />
            <p className="text-sm font-medium text-foreground">
              No support ticket system yet
            </p>
            <p className="mt-1 text-xs text-muted-foreground max-w-xs mx-auto">
              To enable in-app support tickets, create a{" "}
              <code className="font-mono text-[11px] bg-slate-100 px-1 py-0.5 rounded">
                support_requests
              </code>{" "}
              table in Supabase and connect a form on the user-facing settings
              page.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* At-risk users table */}
      <Card className="border-slate-200 shadow-none">
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Users className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base font-semibold">
              Users Needing Attention
            </CardTitle>
          </div>
          <p className="text-xs text-muted-foreground mt-1">
            Users at scan limit, with failed scans in the last 7 days, or who
            have never run a scan.
          </p>
        </CardHeader>
        <CardContent className="p-0">
          {atRiskQuery.isLoading ? (
            <div className="p-4">
              <Table>
                <TableBody>
                  <TableSkeleton />
                </TableBody>
              </Table>
            </div>
          ) : atRiskQuery.isError ? (
            <div className="p-4 text-center text-sm text-red-600">
              Failed to load at-risk users.
            </div>
          ) : atRiskQuery.data?.length === 0 ? (
            <EmptyState
              icon={CheckCircle2}
              title="All users look healthy"
              description="No users are at their scan limit or have recent failed scans."
            />
          ) : (
            <Table>
              <TableHeader>
                <TableRow className="bg-slate-50 hover:bg-slate-50">
                  <TableHead>User</TableHead>
                  <TableHead>Plan</TableHead>
                  <TableHead>Scans</TableHead>
                  <TableHead>Issues</TableHead>
                  <TableHead>Last Scan</TableHead>
                  <TableHead>Signed Up</TableHead>
                  <TableHead className="w-8" />
                </TableRow>
              </TableHeader>
              <TableBody>
                {atRiskQuery.data?.map((user) => (
                  <TableRow
                    key={user.id}
                    className="cursor-pointer hover:bg-slate-50 transition-colors"
                    onClick={() => navigate(`/admin/users/${user.id}`)}
                    aria-label={`View user ${user.email}`}
                  >
                    {/* User */}
                    <TableCell>
                      <div className="space-y-0.5">
                        <p className="text-sm font-medium text-foreground truncate max-w-[160px]">
                          {user.full_name || (
                            <span className="text-muted-foreground">
                              No name
                            </span>
                          )}
                        </p>
                        <p className="font-mono text-[11px] text-muted-foreground truncate max-w-[160px]">
                          {user.email}
                        </p>
                      </div>
                    </TableCell>

                    {/* Plan */}
                    <TableCell>
                      <Badge
                        className={`text-[11px] px-2 py-0.5 capitalize ${
                          PLAN_BADGE_CLASSES[user.plan]
                        }`}
                      >
                        {user.plan}
                      </Badge>
                    </TableCell>

                    {/* Scans used */}
                    <TableCell>
                      <div className="flex items-center gap-1.5">
                        <span
                          className={`text-sm font-medium tabular-nums ${
                            user.at_scan_limit
                              ? "text-red-600"
                              : "text-foreground"
                          }`}
                        >
                          {user.scans_used}/{user.scan_limit}
                        </span>
                        {user.at_scan_limit && (
                          <AlertTriangle className="h-3 w-3 text-amber-500" />
                        )}
                      </div>
                    </TableCell>

                    {/* Risk flags */}
                    <TableCell>
                      <div className="flex flex-wrap gap-1">
                        <RiskBadge
                          active={user.at_scan_limit}
                          label="At limit"
                        />
                        <RiskBadge
                          active={user.has_failed_scans}
                          label="Failed scans"
                        />
                        <RiskBadge
                          active={user.never_scanned}
                          label="Never scanned"
                        />
                        {!user.at_scan_limit &&
                          !user.has_failed_scans &&
                          !user.never_scanned && (
                            <MinusCircle className="h-3.5 w-3.5 text-muted-foreground/40" />
                          )}
                      </div>
                    </TableCell>

                    {/* Last scan */}
                    <TableCell className="text-xs text-muted-foreground">
                      {user.last_scan_date ? (
                        <div className="flex items-center gap-1">
                          <ScanLine className="h-3 w-3" />
                          <span
                            title={format(
                              new Date(user.last_scan_date),
                              "PPpp"
                            )}
                          >
                            {formatDistanceToNow(
                              new Date(user.last_scan_date),
                              { addSuffix: true }
                            )}
                          </span>
                        </div>
                      ) : (
                        <span className="text-muted-foreground/50">Never</span>
                      )}
                    </TableCell>

                    {/* Signed up */}
                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                      <div className="flex items-center gap-1">
                        <Calendar className="h-3 w-3" />
                        {format(new Date(user.created_at), "MMM d, yyyy")}
                      </div>
                    </TableCell>

                    <TableCell>
                      <ChevronRight className="h-4 w-4 text-slate-300" />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

